target.css:
:root {
  --ink: #202635;
  --navy: #29364d;
  --paper: #fffdf8;
  --mist: #e9edf2;
  --line: #cbd3dd;
  --amber: #e6a62c;
  --amber-pale: #fff0c8;
  --red: #c9534d;
  --green: #3d9274;
  --white: #ffffff;
}

.cue-board {
  width: 500px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
  color: var(--ink);
}

.board-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 12px 16px;
  background: var(--navy);
  color: var(--white);
}

.stage-mark {
  display: grid;
  width: 30px;
  height: 30px;
  place-items: center;
  border: 1px solid var(--amber);
  border-radius: 8px;
  color: var(--amber);
  font-size: 17px;
}

.title-block {
  flex: 1;
}

.eyebrow,
.panel-label {
  margin: 0;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.1px;
}

.eyebrow {
  color: var(--amber);
}

.title-block h1 {
  margin: 2px 0 0;
  font-size: 19px;
  line-height: 1;
  font-weight: 700;
}

.live-badge {
  padding: 4px 7px;
  border-radius: 99px;
  background: var(--red);
  color: var(--white);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .8px;
}

.board-grid {
  display: grid;
  grid-template-columns: 132px 1fr;
  min-height: 155px;
}

.rail-panel {
  display: flex;
  flex-direction: column;
  padding: 14px 16px;
  background: var(--amber-pale);
  border-right: 1px solid var(--line);
}

.rail-panel .panel-label {
  color: var(--navy);
}

.set-number {
  margin-top: 5px;
  color: var(--navy);
  font-size: 42px;
  line-height: .9;
  font-weight: 800;
}

.set-caption {
  margin-top: 3px;
  color: var(--navy);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .8px;
}

.rail-rule {
  height: 2px;
  margin: 11px 0 8px;
  background: var(--amber);
}

.load-note {
  margin: 0;
  color: var(--navy);
  font-size: 11px;
  line-height: 1.35;
  font-weight: 600;
}

.cue-panel {
  padding: 13px 16px 10px;
}

.cue-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  padding-bottom: 8px;
  border-bottom: 1px solid var(--mist);
}

.cue-heading .panel-label {
  color: var(--navy);
}

.cue-heading time {
  color: var(--red);
  font-size: 12px;
  font-weight: 800;
}

.cue-list {
  display: grid;
  gap: 1px;
  margin: 6px 0 0;
  padding: 0;
  list-style: none;
}

.cue-list li {
  display: grid;
  grid-template-columns: 12px 1fr auto;
  align-items: center;
  gap: 7px;
  min-height: 28px;
  border-bottom: 1px solid var(--mist);
  font-size: 13px;
  font-weight: 600;
}

.cue-list b {
  font-size: 9px;
  letter-spacing: .6px;
}

.cue-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
}

.cue-dot-ready {
  background: var(--green);
}

.cue-dot-hold {
  background: var(--red);
}

.cue-dot-standby {
  background: var(--amber);
}

.board-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
  background: var(--mist);
}

.footer-status {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--navy);
  font-size: 11px;
  font-weight: 600;
}

.footer-status i {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--green);
}

.board-footer button {
  border: 0;
  border-radius: 6px;
  padding: 7px 11px;
  background: var(--navy);
  color: var(--white);
  font-size: 11px;
  font-weight: 700;
}

